// Mapa zona -> coil Modbus del relé que abre la electroválvula.
const COILS = { 'zona-1': 0, 'zona-2': 1, 'zona-3': 2 };
flow.set('coils', COILS);

if (!flow.get('zonas')) {
    flow.set('zonas', [
        { id: 'zona-1', name: 'Zona 1', running: false, durationMinutes: 15, runsUntil: null, schedule: { enabled: true, startTime: '07:00', days: [1, 3, 5] }, lastWateredAt: null },
        { id: 'zona-2', name: 'Zona 2', running: false, durationMinutes: 20, runsUntil: null, schedule: { enabled: false, startTime: '06:30', days: [0, 2, 4, 6] }, lastWateredAt: null },
        { id: 'zona-3', name: 'Zona 3', running: false, durationMinutes: 10, runsUntil: null, schedule: { enabled: true, startTime: '19:00', days: [0, 1, 2, 3, 4, 5, 6] }, lastWateredAt: null }
    ]);
}

// Deja todos los relés cerrados al arrancar.
return [Object.values(COILS).map((address) => ({
    payload: { value: false, fc: 5, unitid: 1, address, quantity: 1 }
}))];

msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
msg.payload = { zones: flow.get('zonas') || [] };
return msg;

const zonas = flow.get('zonas') || [];
const coils = flow.get('coils') || {};
const zona = zonas.find((z) => z.id === msg.req.params.id);

if (!zona) {
    msg.statusCode = 404;
    msg.headers = { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' };
    msg.payload = { error: 'Zona no encontrada' };
    return [null, msg];
}

const body = msg.payload || {};

if (typeof body.durationMinutes === 'number') {
    zona.durationMinutes = Math.min(240, Math.max(1, Math.round(body.durationMinutes)));
}
if (body.schedule) {
    zona.schedule = Object.assign({}, zona.schedule, body.schedule);
}

let comando = null;
if (typeof body.running === 'boolean' && body.running !== zona.running) {
    zona.running = body.running;
    if (body.running) {
        zona.runsUntil = Date.now() + zona.durationMinutes * 60000;
    } else {
        zona.runsUntil = null;
        zona.lastWateredAt = Date.now();
    }
    comando = {
        payload: { value: zona.running, fc: 5, unitid: 1, address: coils[zona.id], quantity: 1 }
    };
} else if (zona.running) {
    // Cambió la duración mientras riega: se recalcula el fin.
    zona.runsUntil = Date.now() + zona.durationMinutes * 60000;
}

flow.set('zonas', zonas);

msg.headers = { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' };
msg.payload = { zone: zona };
return [comando, msg];

const zonas = flow.get('zonas') || [];
const coils = flow.get('coils') || {};
const ahora = new Date();
const hhmm = String(ahora.getHours()).padStart(2, '0') + ':' + String(ahora.getMinutes()).padStart(2, '0');
const comandos = [];

for (const zona of zonas) {
    // Fin del riego manual o programado.
    if (zona.running && zona.runsUntil !== null && zona.runsUntil <= ahora.getTime()) {
        zona.running = false;
        zona.lastWateredAt = zona.runsUntil;
        zona.runsUntil = null;
        comandos.push({ payload: { value: false, fc: 5, unitid: 1, address: coils[zona.id], quantity: 1 } });
        continue;
    }

    // Arranque programado: una sola vez por minuto de inicio.
    const programado = zona.schedule
        && zona.schedule.enabled
        && zona.schedule.days.indexOf(ahora.getDay()) !== -1
        && zona.schedule.startTime === hhmm;

    if (programado && !zona.running && zona.lastStart !== hhmm + ahora.toDateString()) {
        zona.lastStart = hhmm + ahora.toDateString();
        zona.running = true;
        zona.runsUntil = ahora.getTime() + zona.durationMinutes * 60000;
        comandos.push({ payload: { value: true, fc: 5, unitid: 1, address: coils[zona.id], quantity: 1 } });
    }
}

flow.set('zonas', zonas);
return [comandos];
